Link: https://msgid.link/20240126140218.1033443-1-toke@toke.dk

Here is the root cause:
The bug is caused by the `ath9k_wmi_event_tasklet()` function being executed before the device initialization is complete. This leads to the assumption that all data structures are fully initialized, which is not guaranteed due to the order of initialization. As a result, the function may attempt to access uninitialized data, leading to potential NULL pointer dereferences and other errors.

Here is the patch:

 void ath9k_wmi_event_tasklet(struct tasklet_struct *t)
 {
 	struct wmi *wmi = from_tasklet(wmi, t, wmi_event_tasklet);
 	struct ath9k_htc_priv *priv = wmi->drv_priv;
 	struct wmi_cmd_hdr *hdr;
 	void *wmi_event;
 	struct wmi_event_swba *swba;
 	struct sk_buff *skb = NULL;
 	unsigned long flags;
 	u16 cmd_id;

 	do {
 		spin_lock_irqsave(&wmi->wmi_lock, flags);
 		skb = __skb_dequeue(&wmi->wmi_event_queue);
 		if (!skb) {
 			spin_unlock_irqrestore(&wmi->wmi_lock, flags);
 			return;
 		}
 		spin_unlock_irqrestore(&wmi->wmi_lock, flags);

+		/* Check if ath9k_htc_probe_device() completed. */
+		if (!data_race(priv->initialized)) {
+			kfree_skb(skb);
+			continue;
+		}
+
 		hdr = (struct wmi_cmd_hdr *) skb->data;
 		cmd_id = be16_to_cpu(hdr->command_id);
 		wmi_event = skb_pull(skb, sizeof(struct wmi_cmd_hdr));

 		switch (cmd_id) {
 		case WMI_SWBA_EVENTID:
 			swba = wmi_event;
 			ath9k_htc_swba(priv, swba);
 			break;
 		case WMI_FATAL_EVENTID:
 			ieee80211_queue_work(wmi->drv_priv->hw,
 					     &wmi->drv_priv->fatal_work);
 			break;
 		case WMI_TXSTATUS_EVENTID:
-			/* Check if ath9k_tx_init() completed. */
-			if (!data_race(priv->tx.initialized))
-				break;
-
 			spin_lock_bh(&priv->tx.tx_lock);
 			if (priv->tx.flags & ATH9K_HTC_OP_TX_DRAIN) {
 				spin_unlock_bh(&priv->tx.tx_lock);
 				break;
 			}
 			spin_unlock_bh(&priv->tx.tx_lock);

 			ath9k_htc_txstatus(priv, wmi_event);
 			break;
 		default:
 			break;
 		}

 		kfree_skb(skb);
 	} while (1);
 }



